#include <bits/stdc++.h>
using namespace std;

#define ll long long

int main() {
	int t;
	cin >> t;
	while ( t-- )
	{
	    ll n;
	    cin >> n;
	    
	    ll m = 3 * n;
	    vector<ll> a( m );
	    for ( ll& i : a ) 
	    {
	        cin >> i;    
	    }
	    sort( a.rbegin( ), a.rend( ) );
	    vector<ll> pref( m + 1, 0 );
	    for ( ll i = 0; i < m; i++ )
	    {
	        pref[i + 1] = pref[i] + a[i];
	    }
	    ll ans = 0;
	    for ( ll x = 0; x <= n; x++ )
	    {
	        int low = 0;
	        int high = n - x;
	        
	        while ( low < high ) 
	        {
	            int y = ( low + high ) / 2;
	            int p = x + 2 * y;
	            int q = 3 * n - 2 * x - y;
	            ll diff = a[p] + a[p + 1] - 3 * a[q - 1];
	            if ( diff >= 0 )
	            {
	                low = y + 1;
	            }
	            else high = y;
	        }
	        for ( int y : { low, low - 1 } )
	        {
	            if ( y < 0 || y > n - x )
	            {
	                continue;
	            }
	            int p = x + 2 * y;
	            int q = 3 * n - 2 * x - y;
	            
	            ll value = 2LL * pref[x] + pref[p] + 3LL * pref[q];
	            ans = max( ans, value );
	        }
	    }
	    cout << ans << "\n";
	}
	return 0;
}
